const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const requestText = String(body.documentation_request || body.request || body.message || 'crear documentacion de uso del proyecto');
const topic = String(body.topic || body.doc_topic || 'project-usage');
const audience = String(body.audience || 'humano y agentes del proyecto');
const dryRun = body.dry_run !== false;
const prompt = [
  'Actua como AGENT-DOC-001 para el proyecto Invernadero Central.',
  'Solicitud: ' + requestText + '.',
  'Tema documental: ' + topic + '.',
  'Audiencia: ' + audience + '.',
  'Crea documentacion DRAFT trazable a fuentes versionadas: guias de uso, ejemplos, runbooks, troubleshooting, flujos n8n, agentes, comandos o APIs cuando aplique.',
  'Clasifica afirmaciones como CONFIRMED, DISCOVERED, INFERRED, PROPOSED o UNKNOWN. No documentes como real algo que no este verificado.',
  'Incluye source_refs y separa claramente ejemplos seguros de ejemplos pendientes de validar.',
  'Si documentas pruebas de sensores, aplica project/validation/sensor-test-rigor.yaml: declara nivel de rigor, metodo de referencia, condiciones, evidencia esperada y limitaciones.',
  'No persistas archivos salvo aprobacion humana explicita. No muevas Kanban, no marques DONE, no edites HU congeladas, no compres, no despliegues criticamente ni controles sistemas fisicos.',
  'Si falta informacion critica, haz una sola pregunta.'
].join(' ');
return [{ json: { agent: 'project-documentation', workspace: 'central', prompt, mode: 'wf-documentation-001', approval_required: true, dry_run: dryRun, metadata: { task_id: 'WF-DOCUMENTATION-001', agent_id: 'AGENT-DOC-001', topic, audience, requested_by: body.requested_by || 'chat-gateway' } } }];
